type ctxKey struct{}

func WithLogger(ctx context.Context, l *slog.Logger) context.Context {
    return context.WithValue(ctx, ctxKey{}, l)
}
func From(ctx context.Context) *slog.Logger {
    if l, ok := ctx.Value(ctxKey{}).(*slog.Logger); ok {
        return l
    }
    return slog.Default()
}

// pkg/cmd/root/root.go, inside PersistentPreRunE:
l := f.Logger.With("cmd", cmd.CommandPath())
cmd.SetContext(logs.WithLogger(cmd.Context(), l))
```

The `cmd.SetContext` call must run on the leaf command's
`PersistentPreRunE` (cobra sets it on the specific command under
invocation; children inherit at run time). A helper that runs
before cobra resolves the target command sees a stale context and
the logger attribute never lands.

```go
// pkg/cmd/root/root.go
var verbose int
var logLevel string
root.PersistentFlags().CountVarP(&verbose, "verbose", "v",
    "increase log verbosity (-v=info, -vv=debug)")
root.PersistentFlags().StringVar(&logLevel, "log-level", "",
    "explicit log level (warn|info|debug); overrides -v")

// In PersistentPreRunE.
// Note: cobra's CountVarP starts at 0 and has no way to express
// "explicit -v0", so verbose == 0 and "no -v passed" are the same
// state. That means env-var MYTOOL_LOG wins when no -v/-vv flag is
// present — which is the intended precedence.
lvl := slog.LevelWarn
switch {
case logLevel != "":
    lvl = parseLevel(logLevel) // warn|info|debug
case verbose >= 2:
    lvl = slog.LevelDebug
case verbose == 1:
    lvl = slog.LevelInfo
case os.Getenv("MYTOOL_LOG") != "":
    lvl = parseLevel(os.Getenv("MYTOOL_LOG"))
}
```

```go
// opts here is the root command's options struct (LogFile, LogFormat, etc.).
// The slog handler options get their own name to avoid shadowing.
var w io.Writer = f.IOStreams.ErrOut
if opts.LogFile != "" {
    fh, err := os.OpenFile(opts.LogFile,
        os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
    if err != nil { return err }
    w = fh
}

hopts := &slog.HandlerOptions{Level: lvl}
var h slog.Handler
switch opts.LogFormat {
case "json":
    h = slog.NewJSONHandler(w, hopts)
default:
    h = slog.NewTextHandler(w, hopts)
}
logger := slog.New(h)
