For known-total progress bars, a sibling method:
`f.ProgressBar(ctx context.Context, label string, total int)
progress.Progress`. Same interface, different constructor,
different library underneath.

The TTY spinner impl lives in byob-progress.3 (library-backed via
`charmbracelet/bubbles/spinner`). This decision owns only the
off-TTY `loggingImpl` — the template's own code for the no-TTY
chatter path.

```go
type loggingImpl struct {
    out      io.Writer
    label    string
    lastEmit atomic.Int64
    minGap   time.Duration // default 2s
}

// Update is best-effort under concurrency: two goroutines hitting
// the rate-limit window simultaneously will see both CAS attempts
// and only one will succeed. The loser silently drops, which is
// the intended dedup behavior — progress is advisory, never
// load-bearing.
func (l *loggingImpl) Update(msg string) {
    now := time.Now().UnixNano()
    last := l.lastEmit.Load()
    if now-last < int64(l.minGap) { // time.Duration is int64 ns
        return
    }
    if !l.lastEmit.CompareAndSwap(last, now) {
        return // another goroutine emitted; skip this one
    }
    fmt.Fprintf(l.out, "%s: %s\n", l.label, msg)
}
```

```go
// pkg/cmd/progress/spinner.go
package progress

import (
    "github.com/charmbracelet/bubbles/spinner"
    tea "github.com/charmbracelet/bubbletea"
)

type spinnerImpl struct {
    prog *tea.Program
}

type spinnerModel struct {
    sp    spinner.Model
    label string
    final string
    done  bool
}

type updateLabelMsg string
type stopMsg struct{ final string }

func (m *spinnerModel) Init() tea.Cmd { return m.sp.Tick }
func (m *spinnerModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
    switch msg := msg.(type) {
    case updateLabelMsg:
        m.label = string(msg)
    case stopMsg:
        m.final = msg.final
        m.done = true
        return m, tea.Quit
    case spinner.TickMsg:
        var cmd tea.Cmd
        m.sp, cmd = m.sp.Update(msg)
        return m, cmd
    }
    return m, nil
}
func (m *spinnerModel) View() string {
    if m.done { return m.final }
    return m.sp.View() + " " + m.label
}

func NewSpinner(ctx context.Context, out io.Writer, label string) Progress {
    sp := spinner.New()
    sp.Spinner = spinner.Dot
    m := &spinnerModel{sp: sp, label: label}
    // tea.WithContext causes Program.Run() to return when ctx is
    // cancelled — no separate watcher goroutine needed.
    prog := tea.NewProgram(m, tea.WithOutput(out), tea.WithContext(ctx))
    return &spinnerImpl{prog: prog}
}
func (p *spinnerImpl) Start()            { go func() { _, _ = p.prog.Run() }() }
func (p *spinnerImpl) Update(msg string) { p.prog.Send(updateLabelMsg(msg)) }
func (p *spinnerImpl) Stop()             { p.prog.Send(stopMsg{}) }
func (p *spinnerImpl) Fail(err error)    { p.prog.Send(stopMsg{final: "✗ " + err.Error() + "\n"}) }

// pkg/cmd/progress/bar.go uses schollz/progressbar/v3 similarly
// (standalone, not bubbletea — see tradeoffs above).
